const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const{setup}=require('./baseline-harness.cjs');
const scalar=async(db,q,p=[])=>Object.values((await db.query(q,p)).rows[0]||{})[0];
async function fixture({tiered=false}={}){const db=await setup();await db.exec(fs.readFileSync(path.join(__dirname,tiered?'payload.sql':'retention.sql'),'utf8'));await db.exec("insert into public.ar_config_targets values('AR','IN','RETENTION_A','INR','印度','Asia/Kolkata'),('AR','IN','RETENTION_B','INR','印度','Asia/Kolkata');insert into public.dashboard_platform_team_map values('AR','IN','RETENTION_A','Retention A','Synthetic team','IN','印度',true),('AR','IN','RETENTION_B','Retention B','Synthetic team','IN','印度',true);alter table private.provider_snapshot_artifacts alter column computed_at set default(clock_timestamp()-interval'2hours')");const targets=(await db.query("select to_jsonb(t)t from private.provider_snapshot_native_catalog()t where source='ar'order by id")).rows.map(r=>r.t);for(const t of targets)await db.query('select private.provider_snapshot_register_target($1)',[JSON.stringify(t)]);
 async function cohort(day,hour,{missing=false,lane='current',useTargets=targets,nextDue=null}={}){const cutoff=await scalar(db,"select(($1::date+make_interval(hours=>$2::int))at time zone'Asia/Kolkata')::text",[day,hour]);const id=await scalar(db,"insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,roster_token,targets,supplement_pass)values($1,$2,$3,md5($4::jsonb::text),$4::jsonb,0)returning id",[lane,day,cutoff,JSON.stringify(useTargets)]);let index=0;const jobs=[];
 for(const [component,prior]of [['orders',false],['orders',true],['intake',false],['intake',true],['submission',false]])for(const t of useTargets){const times=(await db.query("select private.provider_snapshot_iso(($1::date-($3::int))::timestamp at time zone'Asia/Kolkata')f,private.provider_snapshot_iso((($1::date-($3::int))+make_interval(hours=>$2::int))at time zone'Asia/Kolkata')e",[day,hour,prior?1:0])).rows[0];const q={action:'aggregate',view:'providers',platformId:t.id,startAt:times.f,endAt:times.e,direction:'charge',status:'all',currency:'INR',offset:0,limit:20};const job=await scalar(db,'select private.provider_snapshot_enqueue($1,$2,$3)',[JSON.stringify(t),JSON.stringify(q),component]);jobs.push(job);if(nextDue)await db.query('update private.provider_snapshot_jobs set next_due_at=$2 where id=$1',[job,nextDue]);await db.query('insert into private.provider_snapshot_cohort_jobs values($1,$2)',[id,job]);
 if(missing&&++index===5*useTargets.length){await db.query("update private.provider_snapshot_jobs set status='failed',attempts=3 where id=$1",[job]);continue;}
 if(await scalar(db,'select exists(select 1 from private.provider_snapshot_heads where job_id=$1)',[job]))continue;
 const payload={version:component==='submission'?3:1,platform:{id:t.id,source:t.source,sourceName:t.source_name,scopeGroup:t.scope_group,currency:t.currency,timezone:t.timezone},startAt:times.f,endAt:times.e};if(component==='orders')Object.assign(payload,{summary:[],groups:{provider:[]},rows:[]});else if(component==='submission')Object.assign(payload,{metrics:[],coverage:{complete:false},rows:null,members:null});else Object.assign(payload,{snapshotWindow:{startAt:times.f,endAt:times.e},rows:[]});
 const provenance={computationComplete:true,upstreamComplete:false,sourceWatermark:{kind:'synthetic'},sourceReadStartedAt:new Date().toISOString(),sourceReadCompletedAt:new Date().toISOString()};const j=await scalar(db,"select private.provider_snapshot_claim('retention-fixture',120)");assert.equal(j.jobId,job);const published=await scalar(db,'select private.provider_snapshot_complete($1,$2,$3,$4,$5)',[j.jobId,j.runId,j.fence,JSON.stringify(payload),JSON.stringify(provenance)]);assert.equal(published.published,true);
 }
 await db.query("update private.provider_snapshot_cohorts set status=$2,updated_at=clock_timestamp()-interval'2hours'where id=$1",[id,missing?'failed':'ready']);return{id,jobs};}
 await db.exec("set statement_timeout='5s'");return{db,targets,cohort,retire:id=>scalar(db,'select private.provider_snapshot_retire_intraday($1)',[id]),gc:n=>scalar(db,'select private.provider_snapshot_gc_versions($1)',[n])};}

module.exports={fixture,scalar};
